import { Project } from '../../../src'
import { runTestOnFunction, validateDiagnostic } from '../../test-utils'
import { ts, path } from '@servicenow/sdk-build-core'

describe('Service Catalog Variable Name Conflict Diagnostic Validation', () => {
    describe('CatalogItem - Variable Name Conflicts', () => {
        test('should fail when CatalogItem has variable name conflict with attached variable set', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSetWithUserInfo = VariableSet({
                    $id: Now.ID['test_varset_user_info'],
                    title: 'User Information',
                    internalName: 'test_varset_user_info',
                    variables: {
                        //@ts-expect-error avoid import
                        userName: ReferenceVariable({
                            question: 'User Name from VariableSet',
                            referenceTable: 'sys_user',
                        }),
                        //@ts-expect-error avoid import
                        department: SingleLineTextVariable({
                            question: 'Department from VariableSet',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItem({
                    $id: Now.ID['test_catalog_item_name_conflict'],
                    name: 'Test Name Conflict',
                    shortDescription: 'Test variable name conflict',
                    variableSets: [
                        {
                            variableSet: varSetWithUserInfo,
                            order: 100,
                        },
                    ],
                    variables: {
                        //@ts-expect-error avoid import
                        userName: SingleLineTextVariable({
                            question: 'User Name from CatalogItem',
                        }),
                        //@ts-expect-error avoid import
                        email: SingleLineTextVariable({
                            question: 'Email',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ObjectLiteralExpression,
                "Variable name conflict: 'userName' is defined in both CatalogItem variables and an attached VariableSet. Each variable must have a unique name across the CatalogItem and all attached VariableSets."
            )
        })

        test('should pass when CatalogItem has no variable name conflicts', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSetWithUserInfo = VariableSet({
                    $id: Now.ID['test_varset_unique'],
                    title: 'User Information',
                    internalName: 'test_varset_unique',
                    variables: {
                        //@ts-expect-error avoid import
                        userName: ReferenceVariable({
                            question: 'User Name',
                            referenceTable: 'sys_user',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItem({
                    $id: Now.ID['test_catalog_item_no_conflict'],
                    name: 'Test No Conflict',
                    shortDescription: 'Test no conflict',
                    variableSets: [
                        {
                            variableSet: varSetWithUserInfo,
                            order: 100,
                        },
                    ],
                    variables: {
                        //@ts-expect-error avoid import
                        email: SingleLineTextVariable({
                            question: 'Email',
                        }),
                        //@ts-expect-error avoid import
                        description: SingleLineTextVariable({
                            question: 'Description',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            // Should have no diagnostic errors
            expect(output).toEqual([])
        })
    })

    describe('RecordProducer - Variable Name Conflicts', () => {
        test('should fail when RecordProducer has variable name conflict with attached variable set', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSetWithIncidentInfo = VariableSet({
                    $id: Now.ID['test_varset_incident'],
                    title: 'Incident Information',
                    internalName: 'test_varset_incident',
                    variables: {
                        //@ts-expect-error avoid import
                        assignedTo: ReferenceVariable({
                            question: 'Assigned To',
                            referenceTable: 'sys_user',
                        }),
                        //@ts-expect-error avoid import
                        priority: SingleLineTextVariable({
                            question: 'Priority',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItemRecordProducer({
                    $id: Now.ID['test_rp_name_conflict'],
                    name: 'Test RP Name Conflict',
                    shortDescription: 'Test',
                    table: 'incident',
                    variableSets: [
                        {
                            variableSet: varSetWithIncidentInfo,
                            order: 100,
                        },
                    ],
                    variables: {
                        //@ts-expect-error avoid import
                        assignedTo: SingleLineTextVariable({
                            question: 'Assigned To from RecordProducer',
                        }),
                        //@ts-expect-error avoid import
                        description: SingleLineTextVariable({
                            question: 'Description',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ObjectLiteralExpression,
                "Variable name conflict: 'assignedTo' is defined in both RecordProducer variables and an attached VariableSet. Each variable must have a unique name across the RecordProducer and all attached VariableSets."
            )
        })

        test('should pass when RecordProducer has no variable name conflicts', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSetWithIncidentInfo = VariableSet({
                    $id: Now.ID['test_varset_incident_unique'],
                    title: 'Incident Information',
                    internalName: 'test_varset_incident_unique',
                    variables: {
                        //@ts-expect-error avoid import
                        assignedTo: ReferenceVariable({
                            question: 'Assigned To',
                            referenceTable: 'sys_user',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItemRecordProducer({
                    $id: Now.ID['test_rp_no_conflict'],
                    name: 'Test RP No Conflict',
                    shortDescription: 'Test',
                    table: 'incident',
                    variableSets: [
                        {
                            variableSet: varSetWithIncidentInfo,
                            order: 100,
                        },
                    ],
                    variables: {
                        //@ts-expect-error avoid import
                        description: SingleLineTextVariable({
                            question: 'Description',
                        }),
                        //@ts-expect-error avoid import
                        urgency: SingleLineTextVariable({
                            question: 'Urgency',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            // Should have no diagnostic errors
            expect(output).toEqual([])
        })
    })

    describe('Edge Cases', () => {
        test('should pass when CatalogItem has variables but no variable sets', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                CatalogItem({
                    $id: Now.ID['test_catalog_no_varsets'],
                    name: 'Test No VariableSets',
                    shortDescription: 'Test',
                    variables: {
                        //@ts-expect-error avoid import
                        userName: SingleLineTextVariable({
                            question: 'User Name',
                        }),
                        //@ts-expect-error avoid import
                        email: SingleLineTextVariable({
                            question: 'Email',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            // Should have no diagnostic errors
            expect(output).toEqual([])
        })

        test('should pass when CatalogItem has variable sets but no direct variables', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSet = VariableSet({
                    $id: Now.ID['test_varset_only'],
                    title: 'Test VariableSet',
                    internalName: 'test_varset_only',
                    variables: {
                        //@ts-expect-error avoid import
                        userName: SingleLineTextVariable({
                            question: 'User Name',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItem({
                    $id: Now.ID['test_catalog_varsets_only'],
                    name: 'Test VariableSets Only',
                    shortDescription: 'Test',
                    variableSets: [
                        {
                            variableSet: varSet,
                            order: 100,
                        },
                    ],
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            // Should have no diagnostic errors
            expect(output).toEqual([])
        })
    })
})
